import java.util.*;

public class Main {
    public static void main(String[] args) {

        // Build an inventory tracker using HashMap
        HashMap<String, Integer> inventory = new HashMap<>();

        inventory.put("Laptop",   50);
        inventory.put("Monitor",  30);
        inventory.put("Keyboard", 120);
        inventory.put("Mouse",    90);

        // Try: reduce Laptop stock by 5 using compute()
        inventory.compute("Laptop", (item, qty) -> qty - 5);

        // Try: add a new item only if absent
        inventory.putIfAbsent("Webcam", 25);

        // Try: remove Mouse if its stock equals 90
        inventory.remove("Mouse", 90);

        // Print final inventory
        System.out.println("Final Inventory:");
        inventory.entrySet().stream()
                 .sorted(Map.Entry.comparingByKey())
                 .forEach(e -> System.out.println(e.getKey() + " : " + e.getValue()));
    }
}

